exercises.solution:
#include <map>
#include <string>
#include <sstream>

std::map<std::string, int> wordCounts(std::string text)
{
    std::map<std::string, int> counts;
    std::istringstream in(text);
    std::string word;
    while (in >> word) counts[word]++;
    return counts;
}

#include <map>
#include <string>
#include <sstream>

std::string mostCommon(std::string text)
{
    std::map<std::string, int> counts;
    std::istringstream in(text);
    std::string word;
    while (in >> word) counts[word]++;
    std::string best;
    int bestCount = 0;
    for (auto& [w, n] : counts)
        if (n > bestCount) { best = w; bestCount = n; }
    return best;
}
